#!/usr/bin/env node
// Turns the DEPLOYMENT MANIFEST (deployment/*.json) into STATIC imports the bundler can follow —
// src/deployment.generated.ts. Hermes/Metro load no code at runtime, so "which client modules ship
// in this deployment's app" must be decided here, at build time; the generated file is the entire
// runtime surface of that decision (App.tsx composes it over the base pack).
//
//   MEMEX_DEPLOYMENT=acme            → deployment/acme.json
//   MEMEX_DEPLOYMENT=/abs/path.json  → that file
//   (unset)                          → deployment/default.json
//
// The DEFAULT output is CHECKED IN so a fresh clone / CI builds without running this; `npm run
// start|web:export` re-run it (pre-scripts), so editing a manifest or switching MEMEX_DEPLOYMENT
// takes effect on the next build. Deterministic: same manifest → byte-identical output.
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const sel = process.env.MEMEX_DEPLOYMENT ?? "default";
const manifestPath = sel.endsWith(".json")
  ? path.resolve(root, sel)
  : path.join(root, "deployment", `${sel}.json`);

if (!fs.existsSync(manifestPath)) {
  console.error(`gen-deployment: manifest not found: ${manifestPath} (MEMEX_DEPLOYMENT=${sel})`);
  process.exit(1);
}
const manifest = JSON.parse(fs.readFileSync(manifestPath, "utf8"));
const name = String(manifest.name ?? sel);
// Module specifiers: a package name passes through; a ./-relative path is relative to the APP ROOT
// in the manifest (author-friendly) and rewritten relative to src/ here, where the generated file
// lives — Metro and tsc both resolve the emitted import from that directory.
const srcDir = path.join(root, "src");
// PLUGIN modules ("plugin:<RepoName>/<path>") are VENDORED: Metro never resolves across repos
// (watchFolders would pin absolute developer paths into the build), so the module's whole
// directory is copied from the plugin checkout into src/deployment.vendor/<RepoName>/<dir>/ and
// imported from there. Deterministic from the checkout's content; the vendor dir is regenerated
// (wiped) on every run and gitignored — the DEFAULT manifest must never reference a plugin, or a
// fresh clone could not build without the plugin checkout.
const vendorRoot = path.join(srcDir, "deployment.vendor");
fs.rmSync(vendorRoot, { recursive: true, force: true });
const pluginRepos = (process.env.MEMEX_PLUGIN_REPOS ?? "")
  .split(":")
  .filter(Boolean)
  .map((p) => path.resolve(p));
const vendorPlugin = (spec) => {
  const ref = spec.slice("plugin:".length);
  const [repoName, ...rest] = ref.split("/");
  if (!repoName || rest.length === 0) {
    console.error(`gen-deployment: malformed plugin specifier '${spec}' — expected plugin:<RepoName>/<path-in-repo>`);
    process.exit(1);
  }
  const repo = pluginRepos.find((p) => path.basename(p) === repoName);
  if (!repo) {
    console.error(
      `gen-deployment: plugin repo '${repoName}' (for '${spec}') is not in MEMEX_PLUGIN_REPOS — `
      + `set it to colon-separated checkout paths whose basename names the repo (the memex-local convention). `
      + `Currently: ${pluginRepos.join(":") || "(unset)"}`);
    process.exit(1);
  }
  const modulePath = rest.join("/");
  const entry = ["", ".tsx", ".ts"].map((ext) => path.join(repo, modulePath + ext)).find((p) => fs.existsSync(p) && fs.statSync(p).isFile());
  if (!entry) {
    console.error(`gen-deployment: plugin module '${modulePath}(.tsx|.ts)' not found under ${repo}`);
    process.exit(1);
  }
  // Copy the module's DIRECTORY (a module may span several files) into the vendor tree at the
  // same repo-relative location, so intra-module relative imports keep working.
  const moduleDir = path.dirname(entry);
  const destDir = path.join(vendorRoot, repoName, path.relative(repo, moduleDir));
  fs.cpSync(moduleDir, destDir, { recursive: true });
  const destEntry = path.join(destDir, path.basename(entry).replace(/\.(tsx|ts)$/, ""));
  return "./" + path.relative(srcDir, destEntry).split(path.sep).join("/");
};
const rewrite = (spec) =>
  spec.startsWith("plugin:")
    ? vendorPlugin(spec)
    : spec.startsWith("./") || spec.startsWith("../")
      ? "./" + path.relative(srcDir, path.resolve(root, spec)).split(path.sep).join("/").replace(/^(?!\.)/, "")
      : spec;
const modules = (Array.isArray(manifest.modules) ? manifest.modules.map(String) : []).map(rewrite);
const branding = manifest.branding ?? {};

const lines = [];
lines.push(`// GENERATED by scripts/gen-deployment.mjs from ${path.relative(root, manifestPath)} — do not edit.`);
lines.push(`// Regenerate: npm run gen:deployment (runs automatically before start/web:export).`);
lines.push(`// This file IS the deployment: the static imports below are how a deployment's client`);
lines.push(`// modules enter the bundle (Hermes loads no code at runtime — build-time composition).`);
lines.push(`import type { DeploymentModule } from "@meshweaver/react/core";`);
modules.forEach((spec, i) => lines.push(`import module${i} from ${JSON.stringify(spec)};`));
lines.push(``);
lines.push(`export const deployment = {`);
lines.push(`  name: ${JSON.stringify(name)},`);
lines.push(`  modules: [${modules.map((_, i) => `module${i} as DeploymentModule`).join(", ")}] as readonly DeploymentModule[],`);
lines.push(`} as const;`);
lines.push(``);

// TWO outputs, deliberately: branding is IMPORT-FREE so the theme/shell can read it without
// entering the module graph (theme → deployment → modules → leaves → theme was an import CYCLE
// that left module maps undefined mid-evaluation); the module list lives in its own file that
// only App imports.
const brandingLines = [
  `// GENERATED by scripts/gen-deployment.mjs from ${path.relative(root, manifestPath)} — do not edit.`,
  `// IMPORT-FREE on purpose: theme/shell read this without touching the module graph (no cycles).`,
  `export const deploymentBranding = {`,
  `  name: ${JSON.stringify(name)},`,
  `  portalUrl: ${JSON.stringify(manifest.portalUrl ?? "http://localhost:5250")},`,
  `  displayName: ${JSON.stringify(branding.displayName ?? name)},`,
  `  accent: ${JSON.stringify(branding.accent ?? "#0f6cbd")},`,
  `  accentDark: ${JSON.stringify(branding.accentDark ?? branding.accent ?? "#4aa3e8")},`,
  `} as const;`,
  ``,
];

const write = (file, content) => {
  const out = path.join(root, "src", file);
  const prev = fs.existsSync(out) ? fs.readFileSync(out, "utf8") : "";
  if (prev !== content) {
    fs.writeFileSync(out, content);
    return true;
  }
  return false;
};
const a = write("deployment.generated.ts", lines.join("\n"));
const b = write("deploymentBranding.generated.ts", brandingLines.join("\n"));
console.log(
  a || b
    ? `gen-deployment: wrote (${name}, ${modules.length} module(s))`
    : `gen-deployment: up to date (${name})`,
);
